package com.mps.settings; import com.mps.auth.security.UserPrincipal; import com.mps.common.ApiResponse; import com.mps.settings.dto.SettingsDtos.*; import com.mps.settings.service.SystemSettingsService; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/settings") @PreAuthorize("hasAnyRole('SUPER_ADMIN','ORG_ADMIN')") public class SystemSettingsController {private final SystemSettingsService service;public SystemSettingsController(SystemSettingsService s){service=s;} @GetMapping public ApiResponse<List<SettingView>> list(@AuthenticationPrincipal UserPrincipal p){return ApiResponse.ok("Settings loaded.",service.list(p));}@PutMapping public ApiResponse<SettingView> put(@AuthenticationPrincipal UserPrincipal p,@Valid @RequestBody UpdateSettingRequest r){return ApiResponse.ok("Setting saved.",service.put(p,r));}}
